SELECT *, AVG(duration_sec) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS duration_sec_avg_5, FIRST_VALUE(page) IGNORE NULLS OVER w_hist AS first_known_page, LAG(duration_sec, 2) OVER (PARTITION BY event_type ORDER BY event_time, id) AS prev_duration_sec FROM web_events WINDOW w_hist AS (PARTITION BY session_id, page ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
